def test_add_returns_row():
    row = add_calculation(1, 2, "+", 3)
    assert row["a"] == 1 and row["b"] == 2 and row["operation"] == "+" and row["result"] == 3 and "id" in row


def test_list_newest_first():
    add_calculation(1, 2, "+", 3)
    add_calculation(4, 5, "-", 9)
    assert [n["result"] for n in list_calculations()] == [9, 3]


def test_list_empty():
    assert list_calculations() == []


