{"thought":"I'll add the logic to handle division by zero and the clear history functionality. I'll also ensure the form submission correctly updates the history list.","action":"write_file","path":"static/app.js","content":"const list = document.getElementById("list");
const count = document.getElementById("count");
const errorBox = document.getElementById("error");
const ORDER = ["a", "operation", "b", "result"];  // how a row reads: the values the user entered, then the computed ones
const INPUTS = 3;

function summary(item) {
  const parts = ORDER.map((f) => (typeof item[f] === "number" ? UI.num(item[f]) : UI.symbol(item[f])));
  parts.splice(INPUTS, 0, "=");
  return parts.join(" ");
}

async function load() {
  UI.loading(list);
  const res = await fetch("/api/calculations");
  const data = await res.json();
  let shown = data.items;
  count.textContent = UI.count(shown.length, "calculation", "calculations");
  // request-hook:loaded
  UI.renderList(list, shown.map((i) => ({ ...i, summary: summary(i) })), (item) => ({
    title: "summary",
    badges: ["operation"],
  }), "Nothing here yet. Add the first one above.");
}

async function clearHistory() {
  const res = await fetch("/api/calculations/clear", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({})
  });
  const data = await res.json();
  if (!res.ok) {
    errorBox.textContent = typeof data.detail === "string" ? data.detail : "Please check your input";
    return;
  }
  UI.toast("History cleared", "success");
  await load();
}

document.getElementById("form").addEventListener("submit", async (ev) => {
  ev.preventDefault();
  errorBox.textContent = "";
  const operation = document.getElementById("operation").value;
  if (operation === "divide" && parseFloat(document.getElementById("b").value) === 0) {
    errorBox.textContent = "Division by zero is not allowed";
    return;
  }
  const res = await fetch("/api/calculations", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ a: parseFloat(document.getElementById("a").value), b: parseFloat(document.getElementById("b").value), operation: operation })
  });
  const data = await res.json();
  if (!res.ok) {
    errorBox.textContent = typeof data.detail === "string" ? data.detail : "Please check your input";
    return;
  }
  document.getElementById("result").textContent = summary(data);
  UI.toast("Added", "success");
  await load();
});

document.getElementById("clear-history").addEventListener("click", clearHistory);

load();"}

